const fs = require('fs');
const zlib = require('zlib');
const { Readable } = require('stream');

// docx files are ZIP archives - let's parse it manually
const buf = fs.readFileSync('testbed/docs/travel_summary.docx');

// Find local file headers (PK\x03\x04)
const entries = [];
let offset = 0;
while (offset < buf.length - 4) {
  if (buf[offset] === 0x50 && buf[offset+1] === 0x4b && buf[offset+2] === 0x03 && buf[offset+3] === 0x04) {
    const fnLen = buf.readUInt16LE(offset + 26);
    const extraLen = buf.readUInt16LE(offset + 28);
    const compMethod = buf.readUInt16LE(offset + 8);
    const compSize = buf.readUInt32LE(offset + 18);
    const uncompSize = buf.readUInt32LE(offset + 22);
    const filename = buf.slice(offset + 30, offset + 30 + fnLen).toString();
    const dataStart = offset + 30 + fnLen + extraLen;
    entries.push({ filename, compMethod, compSize, uncompSize, dataStart });
    offset = dataStart + compSize;
  } else {
    offset++;
  }
}

// Find word/document.xml
const docEntry = entries.find(e => e.filename === 'word/document.xml');
if (docEntry) {
  let data;
  if (docEntry.compMethod === 0) {
    data = buf.slice(docEntry.dataStart, docEntry.dataStart + docEntry.compSize);
  } else {
    data = zlib.inflateRawSync(buf.slice(docEntry.dataStart, docEntry.dataStart + docEntry.compSize));
  }
  const xml = data.toString('utf-8');
  // Extract text content from XML
  const texts = [];
  const regex = /<w:t[^>]*>([^<]*)<\/w:t>/g;
  let match;
  while ((match = regex.exec(xml)) !== null) {
    texts.push(match[1]);
  }
  // Also detect paragraph breaks
  const lines = xml.split(/<\/w:p>/);
  for (const line of lines) {
    const lineTexts = [];
    const r = /<w:t[^>]*>([^<]*)<\/w:t>/g;
    let m;
    while ((m = r.exec(line)) !== null) {
      lineTexts.push(m[1]);
    }
    if (lineTexts.length > 0) {
      console.log(lineTexts.join(''));
    }
  }
}
