const AdmZip = require('adm-zip');
const path = 'testbed/docs/travel_summary.docx';

// Open the docx (zip) file
const zip = new AdmZip(path);
let xml = zip.readAsText('word/document.xml');

// The note to append
const noteText = \"Note: Maya Chen's Seattle travel bookings include both confirmed and cancelled reservations. Please refer to the summary above for details.\";

// Build a new paragraph XML element
const newPara = '<w:p><w:pPr><w:spacing w:after=\"200\"/></w:pPr><w:r><w:t>' + noteText.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/'/g, '&apos;') + '</w:t></w:r></w:p>';

// Insert just before the closing </w:body> tag
xml = xml.replace('</w:body>', newPara + '</w:body>');

// Update the zip and save
zip.updateFile('word/document.xml', Buffer.from(xml, 'utf-8'));
zip.writeZip(path);

console.log('Document updated successfully.');
