cd /workspace && node -e "
const AdmZip = require('adm-zip');
const PDFDocument = require('pdfkit');
const fs = require('fs');

// 1. Extract text paragraphs from the docx
const zip = new AdmZip('testbed/docs/travel_summary.docx');
const xml = zip.readAsText('word/document.xml');

const paragraphs = [];
const pParts = xml.split(/<\/w:p>/);
for (const part of pParts) {
  const texts = [];
  const r = /<w:t[^>]*>([^<]*)<\/w:t>/g;
  let m;
  while ((m = r.exec(part)) !== null) {
    texts.push(m[1]);
  }
  if (texts.length > 0) {
    let line = texts.join('');
    // Decode XML entities
    line = line.replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&apos;/g, \"'\").replace(/&quot;/g, '\"');
    paragraphs.push(line);
  }
}

// 2. Create PDF
const doc = new PDFDocument({ size: 'A4', margin: 50 });
const output = fs.createWriteStream('testbed/docs/travel_summary.pdf');
doc.pipe(output);

for (const para of paragraphs) {
  // Title
  if (para === 'Travel Booking Summary') {
    doc.fontSize(18).font('Helvetica-Bold').text(para, { align: 'center' });
    doc.moveDown(1);
  }
  // Section headers
  else if (['Flights', 'Hotels', 'Car Rentals'].includes(para)) {
    doc.moveDown(0.5);
    doc.fontSize(14).font('Helvetica-Bold').text(para);
    doc.moveDown(0.3);
  }
  // Note line
  else if (para.startsWith('Note:')) {
    doc.moveDown(0.8);
    doc.fontSize(10).font('Helvetica-Oblique').text(para, { align: 'left' });
  }
  // Regular booking lines
  else {
    doc.fontSize(9).font('Helvetica').text(para, { align: 'left' });
    doc.moveDown(0.15);
  }
}

doc.end();
output.on('finish', () => {
  const stats = fs.statSync('testbed/docs/travel_summary.pdf');
  console.log('PDF created successfully: testbed/docs/travel_summary.pdf (' + (stats.size / 1024).toFixed(1) + ' KB)');
});
"
